_CORE_SRC = '# Diagnosis:\n# The champion splits its games with the marginal greedy opponent in both seats;\n# the report does not support a seat-specific explanation. Its denial objective\n# and travel/upkeep accounting are sound, but its search only considers shortest\n# paths followed by permanently staying at one destination. That misses profitable\n# intermediate stops, waiting for forecast demand, and departures timed to a dip.\n# Its opponent prediction also assumes profit-only greedy allocation, even against\n# opponents optimizing score difference. Fractional blended enemy counts further\n# distort the nonlinear sharing formula.\n#\n# Improvements:\n# 1. Coordinate optimization over time-expanded walks, including waiting and\n#    returning home. Every intermediate payout and upkeep payment is included.\n# 2. Separate static, profit-seeking, and denial-seeking opponent scenarios.\n#    Average actual scenario payoffs, not fractional drone positions, and learn\n#    scenario weights from observed next-turn positions.\n#\n# Safety checklist: source availability is tracked independently of arrivals;\n# only adjacent first steps are emitted; moves are aggregated and int-converted;\n# horizons include the current payout and end at turn 99; saved plans are hints\n# only, and are discarded after missed turns or inconsistent feedback.\n\nimport math\nimport time\nfrom collections import deque\n\nTIME_BUDGET = 0.25\n\n\ndef preprocess(n, edges):\n    adj = [[] for _ in range(n)]\n    for a, b in edges:\n        a, b = int(a), int(b)\n        if 0 <= a < n and 0 <= b < n and a != b:\n            adj[a].append(b)\n            adj[b].append(a)\n    for row in adj:\n        row.sort()\n    choices = [sorted([v] + adj[v]) for v in range(n)]\n    return adj, choices\n\n\ndef revenue(a, b, d):\n    denominator = max(5.0 * (a + b), d)\n    return 5.0 * a * d / denominator if denominator > 0.0 else 0.0\n\n\ndef occupancy(plans, n, horizon):\n    counts = [[0] * horizon for _ in range(n)]\n    for source, path in plans:\n        for k, v in enumerate(path):\n            counts[v][k] += 1\n    return counts\n\n\ndef payoff_table(demands, scenarios, probabilities, base, units, denial):\n    n = len(demands)\n    horizon = len(demands[0])\n    tables = [[None] * horizon for _ in range(n)]\n    for v in range(n):\n        upkeep = 0.0 if v == base else 2.0\n        for k in range(horizon):\n            d = demands[v][k]\n            row = [0.0] * (units + 1)\n            for a in range(units + 1):\n                score = -upkeep * a\n                for scenario, probability in zip(scenarios, probabilities):\n                    b = scenario[v][k]\n                    score += probability * (\n                        revenue(a, b, d) - denial * revenue(b, a, d)\n                    )\n                row[a] = score\n            tables[v][k] = row\n    return tables\n\n\ndef optimize(plans, counts, tables, choices, weights, deadline, sweeps):\n    """Exact one-drone best responses on a time-expanded graph."""\n    n = len(choices)\n    horizon = len(weights)\n    for sweep in range(sweeps):\n        order = range(len(plans))\n        if sweep % 2:\n            order = range(len(plans) - 1, -1, -1)\n        changed = False\n        for index in order:\n            if time.perf_counter() >= deadline:\n                return plans, counts\n            source, old = plans[index]\n            for k, v in enumerate(old):\n                counts[v][k] -= 1\n\n            rewards = [[0.0] * n for _ in range(horizon)]\n            for k in range(horizon):\n                weight = weights[k]\n                for v in range(n):\n                    a = counts[v][k]\n                    row = tables[v][k]\n                    rewards[k][v] = weight * (row[a + 1] - row[a])\n\n            # next_value[v] is the optimal future value starting at v.\n            next_value = [0.0] * n\n            policy = [[0] * n for _ in range(horizon)]\n            for k in range(horizon - 1, -1, -1):\n                values = [0.0] * n\n                reward = rewards[k]\n                preferred = old[k]\n                movement_cost = 0.035 * weights[k]\n                inertia = 0.025 * weights[k]\n                for v in range(n):\n                    best = -1.0e100\n                    destination = v\n                    for u in choices[v]:\n                        score = reward[u] + next_value[u]\n                        if u != v:\n                            score -= movement_cost\n                        if u != preferred:\n                            score -= inertia\n                        if score > best + 1.0e-10:\n                            best = score\n                            destination = u\n                    values[v] = best\n                    policy[k][v] = destination\n                next_value = values\n\n            path = []\n            v = source\n            for k in range(horizon):\n                v = policy[k][v]\n                path.append(v)\n                counts[v][k] += 1\n            if path != old:\n                changed = True\n            plans[index] = (source, path)\n        if not changed:\n            break\n    return plans, counts\n\n\nclass Strategy:\n    def __init__(self, player_id: int) -> None:\n        self.player_id = player_id\n        self.map = None\n        self.saved = {}\n        self.last_turn = None\n        self.predicted_next = None\n        self.model_errors = [2.0, 2.0, 2.0]\n        self.bad_reports = 0\n\n    def act(self, obs):\n        start = time.perf_counter()\n        deadline = start + max(0.0, 0.58 * TIME_BUDGET)\n        n = int(obs.get("n_nodes", 0))\n        if n <= 0:\n            return []\n        if self.map is None:\n            self.map = preprocess(n, obs.get("edges", []))\n        adj, choices = self.map\n        mine = list(obs.get("player_drones", []))\n        enemy = list(obs.get("opponent_drones", []))\n        if len(mine) != n or len(enemy) != n:\n            return []\n        base = int(obs["player_base"])\n        enemy_base = int(obs["opponent_base"])\n        turn = int(obs.get("turn", 0))\n        horizon = min(12, 100 - turn)\n        if horizon <= 0:\n            return []\n\n        bad = (obs.get("n_invalid_actions_last_turn", 0) > 0 or\n               not obs.get("action_format_correct_last_turn", True))\n        if bad:\n            self.bad_reports += 1\n        consecutive = self.last_turn is not None and turn == self.last_turn + 1\n        if not consecutive or bad:\n            self.saved = {}\n        if consecutive and self.predicted_next is not None:\n            for j, prediction in enumerate(self.predicted_next):\n                error = 0.5 * sum(abs(enemy[v] - prediction[v])\n                                  for v in range(n))\n                self.model_errors[j] = (\n                    0.72 * self.model_errors[j] + 0.28 * error\n                )\n\n        forecast = obs.get("demand_forecast", [])\n        demands = []\n        for v in range(n):\n            row = forecast[v] if v < len(forecast) else []\n            last = float(row[-1]) if row else 0.0\n            # Exact five-turn information, then a cautious flat extrapolation.\n            demands.append([max(0.0, float(row[k]) if k < len(row) else last)\n                            for k in range(horizon)])\n        weights = [0.94 ** k for k in range(horizon)]\n\n        # Maintain complete future walks, not merely destination commitments.\n        plans = []\n        for s in range(n):\n            saved = self.saved.get(s, [])\n            for j in range(max(0, int(mine[s]))):\n                old = saved[j] if j < len(saved) else []\n                path = []\n                position = s\n                for k in range(horizon):\n                    destination = old[k] if k < len(old) else position\n                    if destination not in choices[position]:\n                        destination = position\n                    path.append(destination)\n                    position = destination\n                plans.append((s, path))\n        own_projection = occupancy(plans, n, horizon)\n        static_enemy = [[int(enemy[v])] * horizon for v in range(n)]\n        scenarios = [static_enemy]\n\n        # Give prediction a bounded share of the call; always retain static\n        # prediction and a legal plan if the budget is exceptionally small.\n        prediction_deadline = min(deadline, start + 0.22 * TIME_BUDGET)\n        enemy_units = sum(enemy)\n        for denial in (0.0, 1.0):\n            if time.perf_counter() >= prediction_deadline:\n                scenarios.append(static_enemy)\n                continue\n            enemy_plans = []\n            for s in range(n):\n                for _ in range(max(0, int(enemy[s]))):\n                    enemy_plans.append((s, [s] * horizon))\n            enemy_counts = [row[:] for row in static_enemy]\n            table = payoff_table(\n                demands, [own_projection], [1.0],\n                enemy_base, enemy_units, denial\n            )\n            enemy_plans, enemy_counts = optimize(\n                enemy_plans, enemy_counts, table, choices, weights,\n                prediction_deadline, 2\n            )\n            scenarios.append(enemy_counts)\n\n        self.predicted_next = [\n            [scenario[v][0] for v in range(n)] for scenario in scenarios\n        ]\n        minimum = min(self.model_errors)\n        likelihood = [math.exp(-(e - minimum) / 2.5)\n                      for e in self.model_errors]\n        total = sum(likelihood)\n        probabilities = [0.12 + 0.64 * x / total for x in likelihood]\n\n        # Near-term prediction weights are learned. Farther out, static play\n        # remains a scenario rather than a fictitious fractional deployment.\n        table = payoff_table(\n            demands, scenarios, probabilities, base, sum(mine), 1.0\n        )\n        sweeps = 4 if self.bad_reports < 2 else 1\n        plans, own_projection = optimize(\n            plans, own_projection, table, choices, weights, deadline, sweeps\n        )\n\n        # Store only the continuation after this turn\'s first step.\n        saved = {}\n        aggregated = {}\n        for source, path in plans:\n            destination = path[0]\n            saved.setdefault(destination, []).append(path[1:])\n            if source != destination:\n                key = (source, destination)\n                aggregated[key] = aggregated.get(key, 0) + 1\n\n        # Replay against START-of-turn availability. Arrivals are never reused.\n        available = [max(0, int(x)) for x in mine]\n        action = []\n        for (source, destination), count in sorted(aggregated.items()):\n            if (0 <= source < n and 0 <= destination < n\n                    and destination in adj[source]):\n                count = min(int(count), available[source])\n                if count > 0:\n                    action.append((int(source), int(destination), int(count)))\n                    available[source] -= count\n\n        self.saved = saved if self.bad_reports < 2 else {}\n        self.last_turn = turn\n        return action\n'
