_FALLBACK_SRC = '# Action format: "[(from_node, to_node, count), ...]"\n# Payout: "capacity_i = drones_i * drone_capacity" and\n# "served_i = capacity_i * demand / max(total_capacity, demand)".\n# Cost: "UPKEEP = 2.0" per drone away from its own base, after moves.\n# Each drone moves at most one edge per turn, using start-of-turn drones only.\n\nfrom collections import deque\n\nTIME_BUDGET = 0.25\n\nN_TURNS = 100\nDRONE_CAPACITY = 5\nUPKEEP = 2.0\n\n\ndef preprocess_map(n, edges):\n    """Static, deterministic shortest paths for the observed map."""\n    adjacency = [[] for _ in range(n)]\n    for a, b in edges:\n        if 0 <= a < n and 0 <= b < n and a != b:\n            adjacency[a].append(b)\n            adjacency[b].append(a)\n    for neighbors in adjacency:\n        neighbors.sort()\n\n    distances = []\n    for source in range(n):\n        distance = [-1] * n\n        distance[source] = 0\n        queue = deque([source])\n        while queue:\n            node = queue.popleft()\n            for neighbor in adjacency[node]:\n                if distance[neighbor] == -1:\n                    distance[neighbor] = distance[node] + 1\n                    queue.append(neighbor)\n        distances.append(distance)\n\n    next_hop = [[-1] * n for _ in range(n)]\n    for source in range(n):\n        for target in range(n):\n            if source == target or distances[source][target] < 0:\n                continue\n            for neighbor in adjacency[source]:\n                if distances[neighbor][target] == distances[source][target] - 1:\n                    next_hop[source][target] = neighbor\n                    break\n    return adjacency, distances, next_hop\n\n\ndef served(own_drones, opponent_drones, demand):\n    """The specification\'s revenue formula, including its zero case."""\n    capacity = DRONE_CAPACITY * own_drones\n    total_capacity = DRONE_CAPACITY * (own_drones + opponent_drones)\n    denominator = max(total_capacity, demand)\n    if denominator <= 0:\n        return 0.0\n    return capacity * demand / denominator\n\n\ndef conservative_plan(obs, distances):\n    """Assign existing drones first, then release only clearly profitable reserves.\n\n    Value only the exact forecast. Charge all travel upkeep, forecast upkeep,\n    and a subsequent return home, without assuming any post-forecast revenue.\n    Returning home is always an available alternative. No score-denial bonus\n    is used, and fresh deployments avoid occupied opposing nodes.\n    """\n    n = len(distances)\n    base = int(obs["player_base"])\n    own = obs["player_drones"]\n    opponent = obs["opponent_drones"]\n    forecast = obs["demand_forecast"]\n    remaining = max(0, N_TURNS - int(obs.get("turn", 0)))\n    if not remaining:\n        return []\n\n    horizon = min(5, remaining)\n    if len(forecast) < n or any(len(row) < horizon for row in forecast):\n        # Missing forecasts are not an invitation to speculate.\n        return [(s, base, int(own[s])) for s in range(n)\n                if s != base and own[s] > 0]\n\n    allocated = [0] * n\n    assignments = {}\n\n    # Allocate drones already away from home before considering new launches.\n    sources = sorted(\n        range(n),\n        key=lambda s: (s == base, -distances[s][base], s)\n    )\n\n    for source in sources:\n        home_distance = distances[source][base]\n        if home_distance < 0:\n            continue\n\n        # After the first return move, upkeep is avoided on reaching home.\n        return_cost = UPKEEP * min(remaining, max(0, home_distance - 1))\n        baseline = -return_cost\n\n        for _ in range(max(0, int(own[source]))):\n            best_target = base\n            best_value = baseline\n            best_distance = home_distance\n\n            # Distance order explicitly prefers nearby, uncomplicated earnings.\n            targets = sorted(range(n), key=lambda t: (distances[source][t], t))\n            for target in targets:\n                if target == base:\n                    continue\n                distance = distances[source][target]\n                if distance < 0:\n                    continue\n                arrival = max(0, distance - 1)\n                if arrival >= horizon:\n                    continue\n\n                # Do not launch or redirect drones into an existing fight.\n                # Units already present may remain if their actual share pays.\n                if opponent[target] > 0 and target != source:\n                    continue\n\n                home_from_target = distances[target][base]\n                if home_from_target < 0:\n                    continue\n                charged_turns = min(\n                    remaining, horizon + max(0, home_from_target - 1)\n                )\n                value = -UPKEEP * charged_turns\n                count = allocated[target]\n                for k in range(arrival, horizon):\n                    demand = float(forecast[target][k])\n                    value += (\n                        served(count + 1, opponent[target], demand)\n                        - served(count, opponent[target], demand)\n                    )\n\n                # Demand a clear surplus over returning. Staying gets a small\n                # preference, but never enough to justify a losing deployment.\n                margin = 0.5 if target == source else 1.0\n                if value <= baseline + margin:\n                    continue\n                if (value > best_value + 1e-9 or\n                    (abs(value - best_value) <= 1e-9 and\n                     (distance, target) < (best_distance, best_target))):\n                    best_value = value\n                    best_target = target\n                    best_distance = distance\n\n            allocated[best_target] += 1\n            if best_target != source:\n                key = (source, best_target)\n                assignments[key] = assignments.get(key, 0) + 1\n\n    return [(source, target, count)\n            for (source, target), count in sorted(assignments.items())]\n\n\ndef legal_action(plan, own, adjacency, next_hop):\n    """Convert destinations to one-edge moves and replay start-state legality."""\n    n = len(adjacency)\n    proposed = {}\n    for source, target, count in plan:\n        if not (0 <= source < n and 0 <= target < n):\n            continue\n        hop = next_hop[source][target]\n        if hop < 0 or hop == source:\n            continue\n        key = (source, hop)\n        proposed[key] = proposed.get(key, 0) + max(0, int(count))\n\n    available = [max(0, int(count)) for count in own]\n    action = []\n    for (source, target), requested in sorted(proposed.items()):\n        if target not in adjacency[source]:\n            continue\n        count = min(requested, available[source])\n        if count <= 0:\n            continue\n        available[source] -= count\n        action.append((int(source), int(target), int(count)))\n    return action\n\n\nclass Strategy:\n    def __init__(self, player_id: int) -> None:\n        self.player_id = player_id\n        self.map_key = None\n        self.map_data = None\n\n    def act(self, obs):\n        n = int(obs.get("n_nodes", 0))\n        if n <= 0:\n            return []\n        own = obs.get("player_drones", [])\n        opponent = obs.get("opponent_drones", [])\n        base = int(obs.get("player_base", -1))\n        if len(own) != n or len(opponent) != n or not 0 <= base < n:\n            return []\n\n        edges = tuple((int(a), int(b)) for a, b in obs.get("edges", []))\n        key = (n, edges)\n        if key != self.map_key:\n            self.map_data = preprocess_map(n, edges)\n            self.map_key = key\n\n        adjacency, distances, next_hop = self.map_data\n        plan = conservative_plan(obs, distances)\n        return legal_action(plan, own, adjacency, next_hop)\n'
